function migrate(raw) {
  return (raw || []).map(c => {
    const seedClass=(window.SEED_CLASSES||[]).find(seed=>seed.id===c.id),seedOrder=new Map((seedClass?.students||[]).map((student,index)=>[student.id,index+1]));
    c.controls ||= []; c.sessions ||= []; c.observations ||= []; c.students ||= [];
    c.continuousColumns ||= {
      activity: { enabled: true, name: "Activités" },
      participation: { enabled: true, name: "Participation" }
    };
    c.continuousColumns.activity ||= { enabled: true, name: "Activités" };
    c.continuousColumns.participation ||= { enabled: true, name: "Participation" };
    c.gradeFormula ||= { weights: {} }; c.gradeFormula.weights ||= {};
    c.controls.forEach(control=>c.gradeFormula.weights[`control:${control.id}`] ??= 1);
    c.gradeFormula.weights.activity ??= 1; c.gradeFormula.weights.participation ??= 1;
    c.students.forEach((s,index) => { s.grades ||= {}; s.activityScore ??= ""; s.participationScore ??= ""; s.bonusPoints ??= 0; s.orderNumber ??= seedOrder.get(s.id)||index+1; s.active ??= true; s.activeSince ??= ""; s.inactiveSince ??= ""; });
    c.sessions.forEach(s => { s.attendance ||= {}; s.status ||= "draft"; });
    c.observations.forEach(o=>{o.studentIds ||= o.studentId?[o.studentId]:[];o.studentId=o.studentIds[0]||null;});
    return c;
  });
}
function loadData() {
  try { const stored = localStorage.getItem(STORAGE_KEY); return migrate(stored ? JSON.parse(stored) : clone(window.SEED_CLASSES || [])); }
  catch { return migrate(clone(window.SEED_CLASSES || [])); }
}
function loadNavigationState() {
  const fallback={view:"home",classId:null,tab:"dashboard",filter:"",openSessions:new Set(),sessionFilters:new Map(),sessionSorts:new Map(),gradeSort:null,studentSort:null,analysisBinWidth:1,analysisZoom:1,scatterZoom:1};
  try {
    const saved=JSON.parse(localStorage.getItem(NAVIGATION_KEY)||"null");
    if(!saved)return fallback;
    const classExists=data.some(item=>item.id===saved.classId),tabs=["dashboard","grades","attendance","students","observations"];
    return {view:saved.view==="class"&&classExists?"class":"home",classId:classExists?saved.classId:null,tab:tabs.includes(saved.tab)?saved.tab:"dashboard",filter:saved.filter||"",openSessions:new Set(saved.openSessions||[]),sessionFilters:new Map(saved.sessionFilters||[]),sessionSorts:new Map(saved.sessionSorts||[]),gradeSort:saved.gradeSort||null,studentSort:saved.studentSort||null,analysisBinWidth:[0.5,1,2].includes(Number(saved.analysisBinWidth))?Number(saved.analysisBinWidth):1,analysisZoom:[1,1.25,1.5].includes(Number(saved.analysisZoom))?Number(saved.analysisZoom):1,scatterZoom:[1,1.35,1.7].includes(Number(saved.scatterZoom))?Number(saved.scatterZoom):1};
  } catch { return fallback; }
}
function persistNavigationState() {
  localStorage.setItem(NAVIGATION_KEY,JSON.stringify({view:state.view,classId:state.classId,tab:state.tab,filter:state.filter,openSessions:[...state.openSessions],sessionFilters:[...state.sessionFilters],sessionSorts:[...state.sessionSorts],gradeSort:state.gradeSort,studentSort:state.studentSort,analysisBinWidth:state.analysisBinWidth,analysisZoom:state.analysisZoom,scatterZoom:state.scatterZoom}));
}
function setDatabaseStatus(status, label) {
  const element = document.getElementById("database-status");
  if (!element) return;
  element.className = `database-status ${status}`;
  element.querySelector("span").textContent = label;
}
function setDatabaseEngine(engine) { databaseLabel=engine==="mysql"?"MySQL":engine==="postgres"?"PostgreSQL":"Base de données"; }
async function writeDatabase(snapshot) {
  setDatabaseStatus("syncing", "Synchronisation…");
  const response = await fetch("/api/classes", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ classes: snapshot })
  });
  if (!response.ok) { const details=await response.json().catch(()=>({}));throw new Error(details.error||"Database save failed"); }
  const result=await response.json();setDatabaseEngine(result.engine);
  databaseReady = true;
  clearTimeout(databaseRetryTimer);
  localStorage.removeItem(DIRTY_KEY);
  setDatabaseStatus("connected", databaseLabel);
}
function scheduleDatabaseReconnect() {
  databaseReady=false;
  clearTimeout(databaseRetryTimer);
  setDatabaseStatus("offline","Reconnexion…");
  databaseRetryTimer=setTimeout(()=>connectDatabase({silent:true}),4000);
}
function queueDatabaseSave() {
  if (!databaseReady) return;
  clearTimeout(databaseSaveTimer);
  databaseSaveTimer = setTimeout(() => {
    const snapshot = clone(data);
    databaseSaveQueue = databaseSaveQueue
      .catch(() => undefined)
      .then(() => writeDatabase(snapshot))
      .catch(error => { console.error("Synchronisation de la base :",error);scheduleDatabaseReconnect();toast("Synchronisation interrompue — nouvelle tentative automatique"); });
  }, 250);
}
function saveData() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  localStorage.setItem(DIRTY_KEY,"1");
  updateNotificationDot();
  queueDatabaseSave();
}
async function connectDatabase({silent=false}={}) {
  try {
    if(localStorage.getItem(DIRTY_KEY)==="1") { databaseReady=true;await writeDatabase(clone(data));render();return; }
    const response = await fetch("/api/classes", { headers: { Accept: "application/json" } });
    if (!response.ok) throw new Error("Database unavailable");
    const payload = await response.json();
    setDatabaseEngine(payload.engine);
    if (payload.empty) {
      await writeDatabase(clone(data));
    } else {
      const needsMigration=payload.classes.some(classItem=>!classItem.gradeFormula||classItem.students.some(student=>student.orderNumber==null||student.active==null)||classItem.observations.some(observation=>!Array.isArray(observation.studentIds)));
      data = migrate(payload.classes);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
      if(needsMigration)await writeDatabase(clone(data));
      render();
    }
    clearTimeout(databaseRetryTimer);
    databaseReady = true;
    setDatabaseStatus("connected", databaseLabel);
  } catch {
    scheduleDatabaseReconnect();
    if(!silent)toast("Base de données indisponible — reconnexion automatique en cours");
  }
}
