  popover.querySelectorAll("[data-date-value]").forEach(b=>b.onclick=()=>selectCalendarDate(root,b.dataset.dateValue));
  popover.querySelector("[data-cal-today]").onclick=()=>selectCalendarDate(root,TODAY);
  popover.querySelector("[data-cal-clear]")?.addEventListener("click",()=>selectCalendarDate(root,""));
