function gradeColumns(c) { return [...c.controls.map(control=>({key:`control:${control.id}`,label:control.name,value:student=>student.grades?.[control.id]})),...continuousColumns(c).map(column=>({key:column.kind,label:column.name||column.fallback,value:student=>student[column.field]}))]; }
