function percentile(sorted, ratio) { if(!sorted.length)return null;const index=(sorted.length-1)*ratio,lower=Math.floor(index),upper=Math.ceil(index);return sorted[lower]+(sorted[upper]-sorted[lower])*(index-lower); }
function gradeAnalysis(values) { const sorted=values.slice().sort((a,b)=>a-b),mean=average(sorted),middle=Math.floor(sorted.length/2),median=sorted.length?(sorted.length%2?sorted[middle]:(sorted[middle-1]+sorted[middle])/2):null,variance=sorted.length?sorted.reduce((sum,value)=>sum+(value-mean)**2,0)/sorted.length:null;return {mean,median,q1:percentile(sorted,.25),q3:percentile(sorted,.75),standardDeviation:variance==null?null:Math.sqrt(variance),min:sorted.length?sorted[0]:null,max:sorted.length?sorted.at(-1):null,passRate:sorted.length?sorted.filter(value=>value>=10).length/sorted.length*100:null}; }
