  openModal(`<div class="modal-head"><div><p class="eyebrow">${escapeHtml(c.name)}</p><h2>Nouveau contrôle</h2></div><button class="modal-close" data-close>×</button></div><form id="control-form"><div class="field"><label>Nom du contrôle</label><input name="name" value="Contrôle ${next}" required maxlength="40"></div>${dateField("date","Date du contrôle (jj/mm/aaaa)",TODAY,true)}<div class="modal-actions"><button type="button" class="button button-ghost" data-close>Annuler</button><button class="button button-primary">Ajouter la colonne</button></div></form>`);
  document.getElementById("control-form").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);if(!fd.get("date")){toast("Choisissez une date");return;}const control={id:slugId("ctrl"),name:fd.get("name"),date:fd.get("date")};c.controls.push(control);c.gradeFormula.weights[`control:${control.id}`]=1;saveData();closeModal();state.tab="grades";render();toast("Contrôle ajouté au carnet et au calcul");};
