  document.getElementById("control-edit-form").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);if(!fd.get("date")){toast("Choisissez une date");return;}control.name=fd.get("name");control.date=fd.get("date");saveData();closeModal();render();toast("Colonne mise à jour");};
