  openModal(`<div class="modal-head"><div><p class="eyebrow">Action sensible</p><h2>${verb} « ${escapeHtml(control.name)} » ?</h2></div><button class="modal-close" data-close>×</button></div><p class="warning-box">${deleting?"La colonne sera supprimée.":"La colonne sera conservée."} ${filled} note${filled===1?"":"s"} seront définitivement effacées.</p><div class="modal-actions"><button class="button button-ghost" data-close>Annuler</button><button class="button button-danger" id="confirm-control-action">${verb}</button></div>`);
