  document.getElementById("observation-student-search").placeholder="Rechercher par N°, nom ou code Massar…";
  const boxes=[...document.querySelectorAll("[data-observation-student]")],count=document.getElementById("observation-selection-count"),updateCount=()=>{const selected=boxes.filter(box=>box.checked).length;count.textContent=selected?`${selected} élève${selected===1?"":"s"} sélectionné${selected===1?"":"s"}`:"Aucun élève — observation générale";};
  boxes.forEach(box=>box.onchange=updateCount);updateCount();document.getElementById("observation-student-search").oninput=e=>{const query=normalizeSearch(e.target.value);document.querySelectorAll("[data-picker-student]").forEach(row=>row.hidden=Boolean(query)&&!row.dataset.search.includes(query));};document.querySelector("[data-clear-observation-students]").onclick=()=>{boxes.forEach(box=>box.checked=false);updateCount();};
  document.getElementById("observation-form").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),studentIds=boxes.filter(box=>box.checked).map(box=>box.value),values={studentId:studentIds[0]||null,studentIds,note:fd.get("note"),reviewDate:fd.get("reviewDate")};if(existing)Object.assign(existing,values);else c.observations.push({id:slugId("obs"),...values,createdAt:new Date().toISOString(),status:"open"});saveData();closeModal();render();toast(existing?"Observation mise à jour":studentIds.length>1?`Observation ajoutée pour ${studentIds.length} élèves`:"Observation enregistrée");};
