function bindChartTooltips() { let tip=document.getElementById("chart-tooltip");if(!tip){tip=document.createElement("div");tip.id="chart-tooltip";tip.className="chart-tooltip";tip.hidden=true;document.body.appendChild(tip);}const show=(element,x,y)=>{tip.textContent=element.dataset.chartTip;tip.hidden=false;const width=tip.offsetWidth,height=tip.offsetHeight;tip.style.left=`${Math.min(innerWidth-width-10,Math.max(10,x+12))}px`;tip.style.top=`${Math.max(10,y-height-12)}px`;},hide=()=>tip.hidden=true;document.querySelectorAll("[data-chart-tip]").forEach(element=>{element.onpointerenter=event=>show(element,event.clientX,event.clientY);element.onpointermove=event=>show(element,event.clientX,event.clientY);element.onpointerleave=hide;element.onfocus=()=>{const rect=element.getBoundingClientRect();show(element,rect.left+rect.width/2,rect.top);};element.onblur=hide;}); }
